// frontend/src/features/tickets/TicketCreate.jsx - Aligned with Your Specified FormData Fields
// Fields: title (required), description (required), priority (High/Medium/Low), status (default "Open"), attachments (optional)
// UI: Clean, attractive, purple theme inspired by Sanchar Helpdesk PDF (C-DAC branding)
import React, { useState } from "react";
import api from "../../api/axios"; // Adjust path if needed
import { useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";

const TicketCreate = () => {
  const [form, setForm] = useState({
    title: "",
    description: "",
    priority: "",
    status:"" // Default as per common practice; adjust to "Medium" if needed
  });
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const user = useSelector((state) => state.auth.user);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append("title", form.title);
      formData.append("description", form.description);
      formData.append("priority", form.priority);
      formData.append("status", form.status); // Fixed/default as per your example

      if (file) {
        formData.append("attachments", file); // Matches your FormData example
      }

      await api.post("/tickets/", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      navigate("/employee"); // Redirect to dashboard after success
    } catch (err) {
      console.error("Ticket creation error:", err);
      setError(
        err.response?.data?.detail ||
          err.response?.data?.message ||
          "Failed to create ticket. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  const isFormValid = form.title && form.description;

  return (
    <div style={styles.container}>
      <h3 style={styles.title}>Create New Sanchar Ticket</h3>

      {error && <div style={styles.errorAlert}>{error}</div>}

      <form onSubmit={handleSubmit} style={styles.form}>
        {/* Ticket Details */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Ticket Information</h4>

          <div style={styles.inputGroup}>
            <label style={styles.label}>Title *</label>
            <input
              type="text"
              name="title"
              style={styles.input}
              placeholder="e.g., Laptop not booting"
              value={form.title}
              onChange={handleChange}
              required
            />
          </div>

          <div style={styles.inputGroup}>
            <label style={styles.label}>Description *</label>
            <textarea
              name="description"
              style={styles.textarea}
              rows="6"
              placeholder="e.g., Laptop stuck on Dell logo..."
              value={form.description}
              onChange={handleChange}
              required
            />
          </div>

          <div style={styles.inputGroup}>
            <label style={styles.label}>Priority</label>
            <select
              name="priority"
              style={styles.select}
              value={form.priority}
              onChange={handleChange}
            >
              <option value="Low">Low</option>
              <option value="Medium">Medium</option>
              <option value="High">High</option>
            </select>
          </div>
        </div>

        {/* Attachment */}
        <div style={styles.section}>
          <h4 style={styles.sectionTitle}>Attachment (Optional)</h4>
          <div style={styles.inputGroup}>
            <label style={styles.label}>Upload File (Image/PDF/Doc)</label>
            <input
              type="file"
              style={styles.fileInput}
              accept="image/*,.pdf,.doc,.docx"
              onChange={handleFileChange}
            />
            <small style={styles.smallText}>
              Attach screenshot, log file, or any evidence (max 5MB recommended)
            </small>
          </div>
        </div>

        <button
          type="submit"
          style={{
            ...styles.submitButton,
            opacity: loading || !isFormValid ? 0.7 : 1,
          }}
          disabled={loading || !isFormValid}
        >
          {loading ? "Submitting..." : "Submit Ticket"}
        </button>
      </form>
    </div>
  );
};

// Clean & Attractive Styles - Purple Theme from Sanchar Helpdesk PDF (C-DAC)
const styles = {
  container: {
    padding: "40px 20px",
    maxWidth: "800px",
    margin: "0 auto",
    background: "linear-gradient(to bottom, #f9faff, #ffffff)",
    minHeight: "100vh",
    fontFamily: "Arial, sans-serif",
  },
  title: {
    fontSize: "32px",
    textAlign: "center",
    marginBottom: "40px",
    color: "#4527a0", // Purple from PDF
    fontWeight: "700",
  },
  errorAlert: {
    padding: "16px",
    background: "linear-gradient(135deg, #ff4d4f, #cf1322)",
    color: "#ffffff",
    borderRadius: "8px",
    marginBottom: "24px",
    textAlign: "center",
  },
  form: {
    background: "#ffffff",
    padding: "32px",
    borderRadius: "16px",
    boxShadow: "0 8px 24px rgba(0,0,0,0.1)",
  },
  section: {
    marginBottom: "32px",
  },
  sectionTitle: {
    fontSize: "22px",
    marginBottom: "20px",
    color: "#4527a0",
    fontWeight: "600",
    borderBottom: "2px solid #4527a0",
    paddingBottom: "8px",
  },
  inputGroup: {
    marginBottom: "20px",
  },
  label: {
    display: "block",
    fontSize: "15px",
    fontWeight: "600",
    color: "#1a1a1a",
    marginBottom: "8px",
  },
  input: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
  },
  textarea: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    resize: "vertical",
  },
  select: {
    width: "100%",
    padding: "12px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
    background: "#ffffff",
    cursor: "pointer",
  },
  fileInput: {
    width: "100%",
    padding: "8px",
    border: "1px solid #d9d9d9",
    borderRadius: "8px",
    fontSize: "15px",
  },
  smallText: {
    display: "block",
    fontSize: "13px",
    color: "#7a7a7a",
    marginTop: "8px",
  },
  submitButton: {
    width: "100%",
    padding: "14px",
    background: "linear-gradient(135deg, #7c4dff, #4527a0)",
    color: "#ffffff",
    border: "none",
    borderRadius: "8px",
    fontSize: "18px",
    fontWeight: "600",
    cursor: "pointer",
  },
};

export default TicketCreate;
